const {electron}=require('./test-app.cjs'),close=require('./close-test-app.cjs'),{DatabaseSync}=require('node:sqlite');
const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict');
const original=JSON.parse(fs.readFileSync(process.argv[2],'utf8')),root=original.root,profile=path.join(process.env.APPDATA,'YimuCraft'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
(async()=>{let app;const report={};try{assert.ok(!fs.existsSync(path.join(profile,'library/managed')));const env={...process.env};delete env.YIMU_DATA_DIR;delete env.ELECTRON_RUN_AS_NODE;
app=await electron.launch({executablePath:path.join(process.env.LOCALAPPDATA,'Programs/YimuCraft/YimuCraft.exe'),args:[],env});const page=await app.firstWindow();await page.waitForFunction(()=>document.querySelector('#status')?.textContent.startsWith('就绪'),{},{timeout:180000});
report.stats=await page.evaluate(()=>window.yimu.command('stats'));assert.equal(report.stats.total,original.connected.total);assert.equal(report.stats.location,original.connected.location);
const db=new DatabaseSync(path.join(report.stats.location,'library.sqlite'),{readOnly:true});report.types=db.prepare('SELECT ext,count(*) count,sum(missing) missing,sum(cover IS NOT NULL) covers,sum(preview IS NOT NULL) previews FROM assets GROUP BY ext ORDER BY count DESC').all();report.missing=db.prepare('SELECT id,path,ext FROM assets WHERE missing=1').all();report.total=db.prepare('SELECT count(*) n FROM assets').get().n;report.linked=db.prepare('SELECT count(*) n FROM external_assets').get().n;report.owned=db.prepare("SELECT count(*) n FROM assets WHERE lower(path) NOT LIKE 'd:%'").get().n;assert.equal(report.owned,0);report.integrity=db.prepare('PRAGMA quick_check').get();db.close();
report.marker=JSON.parse(fs.readFileSync(path.join(report.stats.location,'linked-library.json'),'utf8'));report.samples=Object.fromEntries(Object.entries(original.samples).map(([ext,r])=>[ext,r.items.map(a=>({path:a.path,exists:fs.existsSync(a.path),cover:a.cover,coverExists:!!a.cover&&fs.existsSync(a.cover),preview:a.preview,previewExists:!!a.preview&&fs.existsSync(a.preview)}))]));
await page.evaluate(async ids=>{state.duplicateIds=ids;await refresh();},original.samples.wav.items.map(a=>a.id));await page.screenshot({path:path.join(root,'after-cleanup.png')});report.visual={};for(const ext of ['aep','ffx']){await page.evaluate(async ids=>{state.agentSelection=true;state.duplicateIds=ids;await refresh();},original.samples[ext].items.map(a=>a.id));await page.waitForFunction(()=>[...document.querySelectorAll('.asset img')].some(i=>i.complete&&i.naturalWidth>0));report.visual[ext]=await page.locator('.asset img').evaluateAll(imgs=>imgs.map(i=>({loaded:i.complete&&i.naturalWidth>0})));await page.screenshot({path:path.join(root,ext+'-cards.png')});}report.sourceDbUnchanged=hash('D:/00-aetodo.library/data/aetodo.db')===original.before.sourceDb;assert.ok(report.sourceDbUnchanged);report.protectedUnchanged=Object.entries(original.before.protected).every(([p,h])=>hash(path.join(profile,p))===h);assert.ok(report.protectedUnchanged);report.oldLibraryAbsent=!fs.existsSync(path.join(profile,'library'));report.oldMaterialCopiesAbsent=!fs.existsSync(path.join(profile,'library/managed'));assert.ok(report.oldMaterialCopiesAbsent);report.passed=true;
}catch(e){report.error=e.stack;report.passed=false;process.exitCode=1;}finally{await close(app);fs.writeFileSync(path.join(root,'final.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({passed:report.passed,error:report.error,total:report.total,visible:report.stats?.total,linked:report.linked,missing:report.missing?.length,types:report.types,marker:report.marker}));}})();

